local UIFightTeamSweepRewardNode = Class("UIFightTeamSweepRewardNode")

------------ lifeCycle ------------
function UIFightTeamSweepRewardNode:Awake()
    self:CleanProperties()
    self:InitComponent()
end

function UIFightTeamSweepRewardNode:OnDestroy()
    self:CleanProperties()
    self.controller = nil
    self = nil
end
------------ lifeCycle ------------

function UIFightTeamSweepRewardNode:CleanProperties()
    self.rewards = nil
end

function UIFightTeamSweepRewardNode:InitComponent()
    self.Txt_Title.text = localize("扫荡奖励")
end

function UIFightTeamSweepRewardNode:SetRewards(rewards)
    self.rewards = rewards
    self:RefreshLoopList(#rewards)
    KTool.SetActive(self.RT_RewardEffect, true)
end

function UIFightTeamSweepRewardNode:SetExRewards(rewards)
    -- rewards = {
    --     [1] = {
    --         ["goodsId"] = 3000003,
    --         ["num"] = 857,
    --     }
    -- }
    if not isNull(rewards) and table.count(rewards) > 0 then
        local goodsId = rewards[1].goodsId
        local goodsNum = rewards[1].num
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        self.Img_ExRewardIcon:LoadSprite(vo.photoPath)
        self.Txt_ExRewardNum.text = string.format("x%d", checkInt(goodsNum))
        KTool.SetActive(self.Txt_ExRewardNum.transform.parent.gameObject, true)
    else
        KTool.SetActive(self.Txt_ExRewardNum.transform.parent.gameObject, false)
    end
end

function UIFightTeamSweepRewardNode:SetIndex(index)
    self.Txt_Title.text = localize("第_num_轮扫荡奖励", {_num_ = tostring(index)})
end

---刷新可以挑战玩家的列表
function UIFightTeamSweepRewardNode:RefreshLoopList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function UIFightTeamSweepRewardNode:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local luaIndex = index + 1

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.transform:Find("GoodNode").gameObject, GoodNodeMBPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
    end
    local data = self.rewards[luaIndex]
    local LT_cell = LB_cell.Env
    -- print("[扫荡] 奖励 cell data", table.dump(data, nil, 5))
    LT_cell:Reload(
        {
            id = data.playerEquipment and data.playerEquipment.id,
            goodsId = data.goodsId,
            text = "x" .. data.num,
            isShowNo = true,
            superScript = data.from,
        }
    )
    LT_cell:SetClickButtonAction(
        function(goodsId, uId)
            GameUtils.ShowResultTips(cell.gameObject, goodsId, uId)
        end
    )

    -- 如果列表里面的道具不足9个，这是不需要滑动，等最后一个cell设置完毕，就关闭loopListView组件，停止对drag事件进行响应
    if #self.rewards <= 9 and luaIndex == #self.rewards then
        self.LoopListView.enabled = false
        local scrollRect = self.LoopListView.gameObject:GetComponent(typeof(ScrollRect))
        if isNotNull(scrollRect) then
            scrollRect.enabled = false
        end
    end

    return cell
end

return UIFightTeamSweepRewardNode